INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('1', 'Cintagem prévia, com tinta indelével, dos sobreiros a abater, nos termos do nº 2 do artigo 9.º do Decreto-Lei n.º 169/2001 de 25 de maio, na sua redação atual e comunicação ao ICNF, com a antecedência mínima de trinta dias úteis em relação à data de início do abate, para efeitos de verificação/fiscalização e ser apresentada a informação cartográfica, em formato shapefile, com a identificação destes exemplares.', 'EE', 2, 1),
('2', 'Sinalizar os exemplares de sobreiros / azinheiras, imediatamente adjacentes às áreas de construção, antes de dar início da mesma, para que estes não sejam afetados pela implementação do projeto, bem como delimitar uma área de proteção dos sobreiros existentes, pelo menos, o dobro da projeção da área da copa, no mínimo de 4 m de raio (árvores jovens), onde são interditas quaisquer ações que conduzam ao seu perecimento ou evidente depreciação (como sejam a remoção de terra vegetal ou mobilizações profundas do solo, etc.), que possam danificar as árvores, nomeadamente as raízes, pernadas, ramos e troncos.', 'DO', 2, 2),
('3', 'No planeamento dos trabalhos e na execução dos mesmos, devem ser adotadas todas as práticas e medidas adequadas de modo a reduzir a formação de poeiras na origem, por compactação e pulverização do solo, visando também a redução dos níveis de perda de carbono e de libertação de poeiras e a sua propagação, como: o não uso de máquinas de rastos; redução das movimentações de terras em períodos de ventos e a exposição de solo nu nos períodos de maior pluviosidade e ventos.', 'DO | EE', 2, 3),
('4', 'Divulgar o programa de execução das obras às populações interessadas, designadamente, as populações mais próximas, mediante divulgação em locais públicos, nomeadamente nas Juntas de Freguesia e nas Câmaras Municipais. A informação disponibilizada deve incluir o objetivo, a natureza, a localização da obra, as principais ações a realizar, respetiva calendarização e eventuais afetações à população, designadamente a afetação temporária das acessibilidades.', 'DO | EE', 2, 4),
('5', 'Implementar um mecanismo de atendimento ao público para a receção de reclamações, sugestões e/ou pedidos de informação sobre o projeto. Este mecanismo deve contemplar pontos de atendimento telefónico e através da internet e estes contactos devem estar afixados, pelo menos, à entrada do estaleiro e em cada frente de obra. As reclamações apresentadas devem ser alvo de análise, avaliação dos impactes associados e, caso se justifique, propostas medidas de minimização ou de eliminação do motivo das mesmas.', 'DO | EE', 2, 5),
('6', 'Realizar ações de formação e de sensibilização ambiental para os trabalhadores e encarregados envolvidos na execução das obras, relativamente às ações suscetíveis de causar impactes ambientais e às medidas de minimização a implementar, designadamente normas e cuidados a ter no decurso dos trabalhos. Estas ações devem realizadas anualmente e sempre que sejam admitidos novos trabalhadores. Neste contexto, deve também ser apresentado o PAAO', 'EE | RAA', 2, 6),
('7', 'Implementar sinalização em toda a área de construção do Data Centre para sensibilização dos cuidados a ter com os habitats, fauna e flora existente.', 'EE', 2, 7),
('8', 'Em todas as áreas sujeitas a intervenção, incluindo os locais de intervenção para a colocação dos apoios das linhas elétricas aéreas, e antes do início de qualquer atividade relacionada com a obra, devem ser estabelecidos os limites para além dos quais não deve haver lugar a qualquer perturbação, quer pelas máquinas quer por eventuais depósitos de terras e/ou outros materiais. Consequentemente, os referidos limites devem ser claramente balizados, e não meramente sinalizados, antes do início da obra, devendo permanecer em todo o perímetro, durante a execução da mesma.', 'EE | RAA', 2, 8),
('9', 'Devem ser salvaguardadas todas as espécies arbóreas e arbustivas que não condicionem a execução da obra, em particular os exemplares adultos de espécies arbóreas autóctones, como sobreiro e azinheira. Para o efeito devem ser implementadas medidas de sinalização das árvores e arbustos, fora das áreas a intervencionar, e que, pela proximidade a estas, se preveja que possam ser acidentalmente afetados. A decisão sobre os exemplares a sinalizar deve ser tomada no local. Esta sinalização deve ser mantida durante o período em que a obra decorre no local de cada apoio.', 'EE | RAA', 2, 9),
('10', 'Informar os Serviços Municipais de Proteção Civil e os Gabinetes Técnicos Florestais, bem como os agentes de proteção civil localmente relevantes (Corpos de Bombeiros, por exemplo), designadamente quanto as ações que serão levadas a cabo e respetiva calendarização, de modo a possibilitar um melhor acompanhamento e intervenção, bem como para ponderar a eventual necessidade de atualização dos correspondentes Planos Municipais de Emergência de Proteção Civil e dos Planos Municipais de Defesa da Floresta Contra Incêndios.', 'DO', 2, 10),
('11', 'Efetuar um planeamento de obra de forma a:', 'EE', 2, 11),
('11.1', 'Minimizar acumulações excessivas de tráfego automóvel originadas pelo encerramento temporário de faixas de rodagem (caso aplicável).', 'EE', 2, 12),
('11.2', 'Reduzir ao mínimo o período em que ocorram movimentações de terras, devendo esta fase decorrer preferencialmente em época seca, de modo a minimizar a erosão dos solos e o transporte sólido nas linhas de água.', 'EE', 2, 13),
('11.3', 'Realizar os trabalhos que envolvam intervenções em linhas de água (inclui atravessamentos e drenagem) numa época do ano adequada, de modo que estas apresentem o mínimo escoamento possível.', 'EE', 2, 14),
('11.4', 'Garantir que todas as intervenções no domínio hídrico cumprem a legislação em vigor.', 'EE', 2, 15),
('11.5', 'Adotar as práticas e medidas adequadas de modo a reduzir a formação de poeiras na origem, por compactação e pulverização do solo, visando também a redução dos níveis de perda de carbono e de libertação de poeiras e a sua propagação, como: o não uso de máquinas de rastos; redução das movimentações de terras em períodos de ventos e a exposição de solo nu nos períodos de maior pluviosidade e ventos.', 'EE', 2, 16),
('12', 'Em todas as áreas sujeitas a intervenção, e antes do início de qualquer atividade relacionada com a obra, devem ser estabelecidos os limites para além do quais não deve haver lugar a qualquer perturbação, quer pelas máquinas quer por eventuais depósitos de terras e/ou outros materiais de forma a reduzir a compactação dos solos. No caso da circulação de veículos, e máquinas, deve a mesma realizar-se de forma controlada, fundamentalmente, dentro de corredores balizados. Consequentemente, os referidos limites devem ser claramente balizados considerando uma área de proteção em torno das mesmas, e não meramente sinalizados, antes do início da obra, devendo permanecer em todo o perímetro, durante a execução da mesma.', 'EE | RAA', 2, 17),
('13', 'Em torno de todos os exemplares arbóreos a preservar, e eventualmente arbustivos, se aplicável, quando próximos de áreas intervencionadas, deve ser criada uma área de proteção, no mínimo correspondente a do diâmetro da copa. A balizagem, enquanto medida preventiva e de proteção, deve ser executada em todo o perímetro da linha circular de projeção horizontal da copa, sobre o terreno, do exemplar arbóreo em causa, ou, no mínimo, na extensão voltada para o lado da intervenção.', 'EE | RAA', 2, 18),
('14', 'Considerar a recolha de espécies ou transplantes das que estão presentes nos Biótopos "Prados", "Ripícola" e "Dunar" - Dunas Cinzentas - para serem utilizadas nas áreas dos projetos de integração paisagística.', 'EE | RAA', 2, 19),
('15', 'A equipa dos trabalhos de arqueologia deve estar dimensionada de acordo com os trabalhos previstos efetuar. Esta deve integrar arqueólogos com experiência comprovada na vertente náutica e subaquática superior a 10 anos em registo e escavação subaquática, bem como integrar conservadores-restauradores para definir e implementar as ações de conservação e monitorização.', 'EE | RAP', 2, 20);